import{at as e,it as t,n,vt as r}from"./chunks/framework.CW63qgVu.js";var i=JSON.parse(`{"title":"Configuration","description":"Every retroBITE .env setting: shares, paths, database, reverse proxy, transfers, queue workers, ScreenScraper, RetroAchievements and conversion tools.","frontmatter":{"title":"Configuration","description":"Every retroBITE .env setting: shares, paths, database, reverse proxy, transfers, queue workers, ScreenScraper, RetroAchievements and conversion tools.","order":2},"headers":[],"relativePath":"docs/getting-started/configuration.md","filePath":"docs/getting-started/configuration.md","lastUpdated":1791630612000}`),a={name:`docs/getting-started/configuration.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>retroBITE is configured through environment variables. Set them in a <code>.env</code> file next to your <code>docker-compose.yml</code>, or in your container manager&#39;s variables (Portainer, Dockhand, Synology, Unraid, TrueNAS). <a href="./installation">Installation</a> covers the settings you need for a first start. This page lists them all.</p><p>Everything in the first tables reaches the containers through the Compose file, so a variables editor is enough. The rest is read from <code>.env</code>. In a stack without one, add the setting under the service&#39;s <code>environment:</code> in the Compose file.</p><p>After changing a setting, apply it by recreating the containers:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>Settings left out use the default shown here. At start, the containers write a warning to their log for a default password, debug left on and a missing <code>HOST_IP</code>.</p><h2 id="the-ones-to-set" tabindex="-1">The ones to set <a class="header-anchor" href="#the-ones-to-set" aria-label="Permalink to “The ones to set”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>AUTH_USER</code> / <code>AUTH_PASS</code></td><td><code>retrobite</code></td><td>The account consoles use for SMB and FTP. <strong>Change the password.</strong></td></tr><tr><td><code>DB_PASSWORD</code> / <code>DB_ROOT_PASSWORD</code></td><td><code>retrobite</code></td><td>The database passwords. Set them before the first start.</td></tr><tr><td><code>GAMES_PATH</code></td><td><code>./games</code></td><td>Where your ROM library is on the host.</td></tr><tr><td><code>HOST_IP</code></td><td>none</td><td>This machine&#39;s LAN address.</td></tr><tr><td><code>PS3NETSRV_WHITELIST</code></td><td>none</td><td>Who may connect to ps3netsrv, such as <code>192.168.1.*</code>. It has no login, so leave it empty only on a network you trust.</td></tr><tr><td><code>APP_TIMEZONE</code></td><td><code>UTC</code></td><td>Your time zone, such as <code>Europe/Stockholm</code>.</td></tr><tr><td><code>WEB_PORT</code></td><td><code>81</code></td><td>The host port the web interface answers on.</td></tr><tr><td><code>RETROBITE_TAG</code></td><td><code>develop</code></td><td>The images to run. <code>develop</code> is the newest pre-release, and a version such as <code>20261006-BETA</code> stays on that version. <code>latest</code>, the newest full release, exists from the first one on.</td></tr></tbody></table><h2 id="app" tabindex="-1">App <a class="header-anchor" href="#app" aria-label="Permalink to “App”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>APP_KEY</code></td><td>generated</td><td>Encrypts sessions and the passwords retroBITE stores. When it is empty, a key is generated on the first start and kept in the state volume (<code>STATE_PATH</code>). Set it only to keep a key you already have, such as one an older install had in <code>.env</code>.</td></tr><tr><td><code>APP_ENV</code></td><td><code>production</code></td><td>Leave it as it is. <code>local</code> is for development.</td></tr><tr><td><code>APP_DEBUG</code></td><td><code>false</code></td><td>Shows stack traces and settings in the browser when something fails. Turn it on only to diagnose a problem.</td></tr><tr><td><code>APP_URL</code></td><td><code>http://localhost:81</code></td><td>The address retroBITE is reached at. Set it behind a reverse proxy.</td></tr><tr><td><code>LOG_LEVEL</code></td><td><code>warning</code></td><td><code>debug</code>, <code>info</code>, <code>warning</code> or <code>error</code>.</td></tr><tr><td><code>APP_TIMEZONE</code></td><td><code>UTC</code></td><td>The zone the app tells time in: the dashboard greeting, the times it shows and when the nightly RetroAchievements jobs run. A PHP zone name such as <code>Europe/Stockholm</code>.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Changing the timezone later</p><p>Timestamps are stored in the app&#39;s timezone without an offset. Changing <code>APP_TIMEZONE</code> on an install that already has data shifts the dates written before the change.</p></div><h2 id="network-shares" tabindex="-1">Network shares <a class="header-anchor" href="#network-shares" aria-label="Permalink to “Network shares”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>AUTH_USER</code></td><td><code>retrobite</code></td><td>The account consoles use for SMB and FTP. One account serves both.</td></tr><tr><td><code>AUTH_PASS</code></td><td><code>retrobite</code></td><td>Its password. <strong>Change it.</strong></td></tr><tr><td><code>HOST_IP</code></td><td>detected</td><td>This machine&#39;s LAN address, which vsftpd hands to consoles for passive-mode FTP.</td></tr><tr><td><code>GAME_FOLDERS</code></td><td><code>ps2 ps3 gc wii xbox dreamcast</code></td><td>The console folders created in the library on start.</td></tr><tr><td><code>SMB_SHARES</code></td><td><code>ps2 gc wii</code></td><td>Folders that also get an SMB share of their own, such as the one Open PS2 Loader connects to.</td></tr></tbody></table><p>Left blank, the share container detects <code>HOST_IP</code> from its default route on every start, which suits a laptop that changes networks. Set it to pin one interface on a machine with several. The web container cannot detect it from Docker&#39;s bridge network, so set it if you want the dashboard&#39;s SMB, FTP and ps3netsrv status to be accurate.</p><h2 id="ps3netsrv" tabindex="-1">ps3netsrv <a class="header-anchor" href="#ps3netsrv" aria-label="Permalink to “ps3netsrv”">​</a></h2><p>The share container runs <a href="https://github.com/aldostools/webMAN-MOD/tree/master/_Projects_/ps3netsrv" target="_blank" rel="noreferrer">ps3netsrv</a> on port <code>38008</code>, so webMAN MOD on a PS3 with custom firmware lists and plays games straight from the library, without copying them over. In webMAN MOD&#39;s setup page, add a network server with this machine&#39;s address and port <code>38008</code>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>PS3NETSRV</code></td><td><code>true</code></td><td>Runs ps3netsrv. <code>false</code> turns it off.</td></tr><tr><td><code>PS3NETSRV_FOLDERS</code></td><td><code>PS3ISO=ps3 PS2ISO=ps2 PSXISO=psx</code></td><td>Which of webMAN MOD&#39;s lists ps3netsrv serves, and the library folder behind each. Add <code>PSPISO=psp</code> for PSP games, and list a console folder here if you moved it. Only webMAN&#39;s own names (<code>PS3ISO</code>, <code>PS2ISO</code>, <code>PSXISO</code>, <code>PSPISO</code>, <code>BDISO</code>, <code>DVDISO</code>, <code>GAMES</code>, <code>PKG</code>) are taken.</td></tr><tr><td><code>PS3NETSRV_WHITELIST</code></td><td>none</td><td>Who may connect: one address, with <code>*</code> for any part, such as <code>192.168.1.*</code> or one PS3&#39;s address. A range such as <code>192.168.1.0/24</code> is not understood, and ps3netsrv then does not start at all (the log says why).</td></tr></tbody></table><p>Set these on both containers, as the Compose file does: the share container runs ps3netsrv from them, and the web container shows its status card, the consoles it serves and who may connect.</p><div class="warning custom-block"><p class="custom-block-title">No login</p><p>ps3netsrv is read-only: webMAN MOD can list and stream, but nothing can be created, changed or deleted through it. It has no username or password, though, so anyone else on the network can read the folders it serves. Set <code>PS3NETSRV_WHITELIST</code> to limit who connects.</p></div><p>webMAN MOD mounts PS1 games as <code>.bin</code>/<code>.cue</code>, <code>.iso</code> or <code>.img</code>, and PS2 games as <code>.iso</code>, not <code>.chd</code>, <code>.cso</code>, <code>.zso</code> or <code>.ecm</code>. <a href="./../guide/conversion">Conversion</a> turns those back into ISO or BIN. PS2 games run through the PS3&#39;s own PS2 emulation, so compatibility depends on the PS3 model.</p><h2 id="paths" tabindex="-1">Paths <a class="header-anchor" href="#paths" aria-label="Permalink to “Paths”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>GAMES_PATH</code></td><td><code>./games</code></td><td>Where your ROM library is on the host. Mounted into both containers and shared as <code>/games</code> over SMB and FTP, and to webMAN MOD over ps3netsrv.</td></tr><tr><td><code>DOCS_PATH</code></td><td><code>./docs</code></td><td>Where your hardware docs are kept on the host.</td></tr><tr><td><code>DB_PATH</code></td><td>volume <code>retrobite-db</code></td><td>The database.</td></tr><tr><td><code>MEDIA_PATH</code></td><td>volume <code>retrobite-media</code></td><td>Downloaded artwork. It can be fetched again.</td></tr><tr><td><code>STATE_PATH</code></td><td>volume <code>retrobite-state</code></td><td>The application key and the live-update keys. <strong>Back it up with the database</strong>: the stored passwords cannot be read without the key.</td></tr></tbody></table><p>Point the volumes at folders of your own, such as <code>/volume1/docker/retrobite/db</code>, to keep them with the rest of a NAS&#39;s backed-up shares.</p><h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to “Database”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>DB_DATABASE</code></td><td><code>retrobite</code></td><td>The database name.</td></tr><tr><td><code>DB_USERNAME</code></td><td><code>retrobite</code></td><td>The database user.</td></tr><tr><td><code>DB_PASSWORD</code></td><td><code>retrobite</code></td><td>The database user&#39;s password.</td></tr><tr><td><code>DB_ROOT_PASSWORD</code></td><td><code>retrobite</code></td><td>MariaDB&#39;s root password. Only the database container reads it.</td></tr></tbody></table><p>MariaDB sets these when the database is first created. Change them before the first start: editing them afterwards does not change the existing database.</p><h2 id="share-on-its-own-address" tabindex="-1">Share on its own address <a class="header-anchor" href="#share-on-its-own-address" aria-label="Permalink to “Share on its own address”">​</a></h2><p>Only with <code>docker-compose.macvlan.yml</code>. See <a href="./installation#when-ports-445-139-and-21-are-taken">When ports 445, 139 and 21 are taken</a>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>SHARE_IP</code></td><td>none</td><td>The share container&#39;s own LAN address. Consoles connect here.</td></tr><tr><td><code>SHARE_SUBNET</code></td><td>none</td><td>The LAN, such as <code>192.168.1.0/24</code>.</td></tr><tr><td><code>SHARE_GATEWAY</code></td><td>none</td><td>The router, such as <code>192.168.1.1</code>.</td></tr><tr><td><code>SHARE_PARENT</code></td><td><code>eth0</code></td><td>The host&#39;s LAN interface.</td></tr></tbody></table><h2 id="reverse-proxy" tabindex="-1">Reverse proxy <a class="header-anchor" href="#reverse-proxy" aria-label="Permalink to “Reverse proxy”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>TRUSTED_PROXIES</code></td><td>none</td><td>Proxies whose <code>X-Forwarded-*</code> headers are trusted, comma-separated, or <code>*</code> for any.</td></tr></tbody></table><p>Set this when retroBITE sits behind a reverse proxy that serves HTTPS. Without it, links come out as <code>http://</code> and the browser blocks them.</p><h2 id="transfers" tabindex="-1">Transfers <a class="header-anchor" href="#transfers" aria-label="Permalink to “Transfers”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>TRANSFER_LOCALHOST_URL</code></td><td><code>http://localhost:81</code></td><td>Copying to a USB drive or SD card works only on HTTPS or <code>localhost</code> in Chrome and Edge. Pages opened another way link here. The Compose file sets it to the published port.</td></tr><tr><td><code>TRANSFER_DISCOVERY_NAMES</code></td><td><code>batocera,recalbox,retropie</code></td><td>Host names to look for when searching the network for shares in <strong>Settings → Destinations</strong>.</td></tr><tr><td><code>TRANSFER_DISCOVERY_SUBNETS</code></td><td>the <code>HOST_IP</code> network</td><td>Networks to scan for the SMB port, such as <code>192.168.1.0/24</code>.</td></tr></tbody></table><p>Docker&#39;s bridge network blocks mDNS and NetBIOS, so the destination search scans the network <code>HOST_IP</code> is on, or the subnets set here. Copying to a share you add by hand works either way.</p><h2 id="queue-workers" tabindex="-1">Queue workers <a class="header-anchor" href="#queue-workers" aria-label="Permalink to “Queue workers”">​</a></h2><p>Background jobs run on separate queues, each with its own workers. One worker per queue unless set here. <code>0</code> starts none.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Queue</th></tr></thead><tbody><tr><td><code>QUEUE_WORKERS_SCRAPER</code></td><td><code>1</code></td><td>Identification and ratings</td></tr><tr><td><code>QUEUE_WORKERS_MEDIA</code></td><td><code>1</code></td><td>Artwork downloads from ScreenScraper</td></tr><tr><td><code>QUEUE_WORKERS_DEFAULT</code></td><td><code>1</code></td><td>Scans and file counts</td></tr><tr><td><code>QUEUE_WORKERS_TOOLBOX</code></td><td><code>1</code></td><td>Loader exports and license ID reading</td></tr><tr><td><code>QUEUE_WORKERS_CONVERSION</code></td><td><code>1</code></td><td>Disc image conversion, one disc at a time</td></tr><tr><td><code>QUEUE_WORKERS_THUMBNAILS</code></td><td><code>1</code></td><td>Cover thumbnails</td></tr><tr><td><code>QUEUE_WORKERS_RA</code></td><td><code>1</code></td><td>RetroAchievements identification and sets</td></tr><tr><td><code>QUEUE_WORKERS_RA_PROGRESS</code></td><td><code>1</code></td><td>RetroAchievements unlocks</td></tr><tr><td><code>QUEUE_WORKERS_HASH</code></td><td><code>1</code></td><td>Checksums and RetroAchievements hashes</td></tr><tr><td><code>QUEUE_WORKERS_TRANSFER</code></td><td><code>3</code></td><td>Copies to network shares</td></tr></tbody></table><p>Media and hash are the ones worth raising on a machine with room to spare. Scraper workers only add speed up to the number of threads your ScreenScraper account allows: 1 on a free account, 6 on Gold. <strong>Settings → ScreenScraper</strong> shows yours.</p><h2 id="screenscraper" tabindex="-1">ScreenScraper <a class="header-anchor" href="#screenscraper" aria-label="Permalink to “ScreenScraper”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>SCREENSCRAPER_DEV_ID</code></td><td>built in</td><td>Your own ScreenScraper developer ID, in place of the one retroBITE ships with. Set both or neither.</td></tr><tr><td><code>SCREENSCRAPER_DEV_PASSWORD</code></td><td>built in</td><td>Its password.</td></tr><tr><td><code>SCREENSCRAPER_CONNECT_TIMEOUT</code></td><td><code>15</code></td><td>Seconds to wait for a connection.</td></tr><tr><td><code>SCREENSCRAPER_TIMEOUT</code></td><td><code>90</code></td><td>Seconds to wait for an answer.</td></tr></tbody></table><p>Your personal ScreenScraper account goes in <strong>Settings → ScreenScraper</strong>, not in <code>.env</code>.</p><h2 id="retroachievements" tabindex="-1">RetroAchievements <a class="header-anchor" href="#retroachievements" aria-label="Permalink to “RetroAchievements”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>RETROACHIEVEMENTS_CONNECT_TIMEOUT</code></td><td><code>15</code></td><td>Seconds to wait for a connection.</td></tr><tr><td><code>RETROACHIEVEMENTS_TIMEOUT</code></td><td><code>180</code></td><td>Seconds to wait for an answer.</td></tr><tr><td><code>RA_HASHER_PATH</code></td><td><code>/usr/local/bin/RAHasher</code></td><td>The RAHasher binary in the web image.</td></tr><tr><td><code>RA_HASHER_TIMEOUT</code></td><td><code>1800</code></td><td>Seconds one hash may take. A CHD on a slow disk can take minutes.</td></tr></tbody></table><h2 id="conversion" tabindex="-1">Conversion <a class="header-anchor" href="#conversion" aria-label="Permalink to “Conversion”">​</a></h2><p>The conversion tools ship in the web image. Override a path only to use a different build.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>CONVERSION_CONCURRENCY</code></td><td><code>1</code></td><td>Conversions run at once. Raise <code>QUEUE_WORKERS_CONVERSION</code> to match. Past the disk&#39;s speed, a second conversion only slows both.</td></tr><tr><td><code>CONVERSION_TIMEOUT</code></td><td><code>7000</code></td><td>Seconds one conversion may take, every disc and step included.</td></tr><tr><td><code>CHDMAN_PATH</code></td><td><code>/usr/local/bin/chdman</code></td><td>chdman</td></tr><tr><td><code>MAXCSO_PATH</code></td><td><code>/usr/local/bin/maxcso</code></td><td>maxcso</td></tr><tr><td><code>ECM_PATH</code> / <code>UNECM_PATH</code></td><td><code>/usr/local/bin/ecm</code>, <code>/usr/local/bin/unecm</code></td><td>ecm and unecm</td></tr><tr><td><code>CUE2POPS_PATH</code> / <code>POPS2CUE_PATH</code></td><td><code>/usr/local/bin/cue2pops</code>, <code>/usr/local/bin/pops2cue</code></td><td>cue2pops and pops2cue</td></tr><tr><td><code>NODTOOL_PATH</code></td><td><code>/usr/local/bin/nodtool</code></td><td>nodtool</td></tr><tr><td><code>EXTRACT_XISO_PATH</code></td><td><code>/usr/local/bin/extract-xiso</code></td><td>extract-xiso</td></tr></tbody></table><h2 id="live-updates" tabindex="-1">Live updates <a class="header-anchor" href="#live-updates" aria-label="Permalink to “Live updates”">​</a></h2><p>Pages update live over Laravel Reverb, which runs inside the web container. Its keys are generated on first start and kept in the state volume, so nothing needs filling in. To pin them, set <code>REVERB_APP_ID</code>, <code>REVERB_APP_KEY</code> and <code>REVERB_APP_SECRET</code>.</p>`,49)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};